def expand_encoded(encoded: str) -> str:
    stack: list[tuple[str, int]] = []
    cur = ''
    num = ''
    for ch in encoded:
        if ch.isdigit():
            num += ch
        elif ch == '[':
            stack.append((cur, int(num)))
            cur = ''
            num = ''
        elif ch == ']':
            prev, k = stack.pop()
            cur = prev + cur * k
        else:
            cur += ch
    return cur
